import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Extract text content with fallback chain
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const bodyItem = items.find(item => item.role === 'body') || items[0];
  const textStr = bodyItem?.text ?? 'A machined-metal watch atelier landing with catalog, pricing, jo';

  // Parse colors from spec
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const group = new THREE.Group();

  // Create backdrop plane (7x6 units) with engineered gradient
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const gradStops = config.intent?.visualSpec?.gradientStops ?? [
    { offset: 0, color: colors.surface },
    { offset: 1, color: colors.ink }
  ];

  const uvNode = uv();
  const gradientColor = mix(
    new THREE.Color(gradStops[0].color),
    new THREE.Color(gradStops[1].color),
    uvNode.y
  );

  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: gradientColor,
    transparent: true
  });

  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // Create main text element
  const textOpts = {
    fontSize: 31,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 480,
    letterSpacingPx: 0
  };

  const textMesh = ctx.fontAtlas.createText(textStr, textOpts);
  textMesh.position.set(-2.8, 1.2, 0.1);
  textMesh.scale.set(0.08, 0.08, 0.08); // Scene-unit scale for body text
  group.add(textMesh);

  // Load and apply image texture if available
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then(texture => {
      const planeGeo = new THREE.PlaneGeometry(3.5, 2.2);
      const planeMat = new MeshBasicNodeMaterial({
        map: texture,
        transparent: true
      });
      const plane = new THREE.Mesh(planeGeo, planeMat);
      plane.position.set(1.5, 0.5, 0.05);
      group.add(plane);
    });
  }

  // Apply scene position
  if (config.scenePosition) {
    group.position.copy(config.scenePosition);
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    backdropGeo.dispose();
    backdropMat.dispose();
    gsap.killTweensOf(group);
    gsap.killTweensOf(textMesh);
  };

  // Attach empty handlers object for future interactivity
  group.userData.handlers = {};

  return group;
}
